export declare function registerTools(tools: AgentTool[]): void;
export declare function getTool(name: string): AgentTool | undefined;
export declare function listTools(phase?: number): AgentTool[];
export declare function listToolNames(phase?: number): string[];
export declare function toolCount(): number;
export declare function hasTool(name: string): boolean;
/**
 * 执行指定工具。会检查工具是否存在。
 * 权限和 Phase 检查由调用方（Orchestrator）通过 before_tool_call 钩子处理。
 */
export declare function executeTool(name: string, input: Record<string, unknown>, ctx: AgentToolContext): Promise<{
    content: string;
}>;
